import{_ as l,C as c,o,c as h,a2 as a,b as i,w as e,a as d,E as n,a3 as s}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse('{"title":"Performance Overview","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/performance/overview.md","filePath":"openshield-xdp/performance/overview.md","lastUpdated":1782568991000}'),p={name:"openshield-xdp/performance/overview.md"};function m(g,t,u,f,b,v){const r=c("Mermaid");return o(),h("div",null,[t[2]||(t[2]=a('<h1 id="performance-overview" tabindex="-1">Performance Overview <a class="header-anchor" href="#performance-overview" aria-label="Permalink to &quot;Performance Overview&quot;">​</a></h1><p>OpenShield-XDP is designed for high-throughput edge filtering with sub-microsecond per-packet overhead. This page documents the performance targets, measurement methodology, and design decisions behind the numbers.</p><h2 id="design-targets" tabindex="-1">Design Targets <a class="header-anchor" href="#design-targets" aria-label="Permalink to &quot;Design Targets&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Metric</th><th>Target</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Normal path latency</strong> (passthrough)</td><td>~300–500 ns</td><td>Packet passes all checks, no mitigation triggered</td></tr><tr><td><strong>Attack path latency</strong> (drop)</td><td>~1–2 µs</td><td>Full pipeline with ban insertion + event emission</td></tr><tr><td><strong>Single-core throughput at 10M PPS</strong></td><td>~50–70% CPU utilization</td><td>On modern Xeon/EPYC cores</td></tr><tr><td><strong>Bloom filter savings</strong></td><td>~60–100 ns/packet</td><td>Skipped whitelist HASH lookup when filter negative</td></tr><tr><td><strong>Per-IP stats update</strong></td><td>~50–80 ns</td><td>LRU_HASH lookup + increment + BPF_ANY update</td></tr><tr><td><strong>Ban insertion</strong></td><td>~200–300 ns</td><td>LRU_HASH insert + ringbuf event emission</td></tr><tr><td><strong>Config read</strong></td><td>~10–20 ns</td><td>ARRAY map with single entry — always hot in L1 cache</td></tr></tbody></table><h2 id="measurement-methodology" tabindex="-1">Measurement Methodology <a class="header-anchor" href="#measurement-methodology" aria-label="Permalink to &quot;Measurement Methodology&quot;">​</a></h2><p>All latency figures are estimated from a combination of:</p><ul><li><code>bpftool prog profile</code> instruction counts × CPU cycle estimates</li><li>Direct measurement via <code>bpf_ktime_get_ns()</code> instrumentation (for non-production builds)</li><li>Synthetic benchmarking with <code>pktgen</code> / <code>hping3</code> at line rate</li></ul><div class="info custom-block"><p class="custom-block-title">Measurement Caveats</p><p>Actual latency depends on CPU model, kernel version, Spectre/Meltdown mitigations, and NIC driver. The figures above are for a kernel 6.6+ system with <code>mitigations=off</code>.</p></div><h2 id="pipeline-cost-breakdown" tabindex="-1">Pipeline Cost Breakdown <a class="header-anchor" href="#pipeline-cost-breakdown" aria-label="Permalink to &quot;Pipeline Cost Breakdown&quot;">​</a></h2>',9)),(o(),i(s,null,{default:e(()=>[n(r,{id:"mermaid-134",class:"mermaid",graph:"pie%20title%20Per-Packet%20Cost%20Distribution%20(Normal%20Path)%0A%20%20%20%20%22MAC%20filter%22%20%3A%205%0A%20%20%20%20%22Packet%20parse%22%20%3A%2040%0A%20%20%20%20%22Whitelist%20(Bloom)%22%20%3A%2060%0A%20%20%20%20%22Ban%20check%22%20%3A%2030%0A%20%20%20%20%22Validation%20(private%2Fbogon)%22%20%3A%2040%0A%20%20%20%20%22Rate%20scoring%22%20%3A%20200%0A%20%20%20%20%22Connection%20tracking%22%20%3A%20100%0A%20%20%20%20%22Config%20read%22%20%3A%2015%0A%20%20%20%20%22Other%20overhead%22%20%3A%2020%0A"})]),fallback:e(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[3]||(t[3]=a('<p>The normal path spends most of its time in <strong>rate scoring</strong> and <strong>connection tracking</strong> — both involve LRU map lookups, which are the most expensive per-packet operation.</p><h2 id="map-operation-costs" tabindex="-1">Map Operation Costs <a class="header-anchor" href="#map-operation-costs" aria-label="Permalink to &quot;Map Operation Costs&quot;">​</a></h2><p>BPF map type strongly influences latency:</p><table tabindex="0"><thead><tr><th>Map Type</th><th>Lookup Cost</th><th>Update Cost</th><th>Notes</th></tr></thead><tbody><tr><td><code>ARRAY</code></td><td>~10 ns</td><td>~10 ns</td><td>Direct indexed access, no hashing. Used for config, baseline, prof.</td></tr><tr><td><code>PERCPU_ARRAY</code></td><td>~15 ns</td><td>~15 ns</td><td>Per-CPU sub-arrays, no lock. Used for global_stats, panic_bucket, prof.</td></tr><tr><td><code>HASH</code> (small)</td><td>~50–80 ns</td><td>~80–120 ns</td><td>Hash computation + collision chain walk. Used for whitelist.</td></tr><tr><td><code>LRU_HASH</code> (large)</td><td>~80–150 ns</td><td>~150–300 ns</td><td>Like HASH + LRU list maintenance. Used for ip_stats, ban.</td></tr><tr><td><code>LPM_TRIE</code></td><td>~100–200 ns</td><td>~200–400 ns</td><td>Prefix matching. Used for subnet bans.</td></tr><tr><td><code>RINGBUF</code> (reserve+submit)</td><td>N/A</td><td>~200–500 ns</td><td>Memory reservation + commit. Used for events.</td></tr></tbody></table><p><strong>Key insight</strong>: ARRAY maps are ~10× cheaper than LRU_HASH maps. This is why <code>config_map</code> and <code>baseline_map</code> use ARRAY — they&#39;re accessed on every packet.</p><h2 id="bloom-filter-impact" tabindex="-1">Bloom Filter Impact <a class="header-anchor" href="#bloom-filter-impact" aria-label="Permalink to &quot;Bloom Filter Impact&quot;">​</a></h2><p>The Bloom filter accelerates whitelist-negative packets:</p>',7)),(o(),i(s,null,{default:e(()=>[n(r,{id:"mermaid-257",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BPacket%5D%20--%3E%20B%7BBloom%20check%7D%0A%20%20%20%20B%20--%3E%7C%22Negative%20(~99.99%25)%22%7C%20C%5B%22Skip%20HASH%20lookup%3Cbr%2F%3E%2B60-100%20ns%20saved%22%5D%0A%20%20%20%20B%20--%3E%7C%22Positive%20(~0.01%25)%22%7C%20D%5B%22Full%20HASH%20lookup%3Cbr%2F%3E(normal%20cost)%22%5D%0A%20%20%20%20C%20--%3E%20E%5BContinue%20pipeline%5D%0A%20%20%20%20D%20--%3E%20F%7BIn%20whitelist%3F%7D%0A%20%20%20%20F%20--%3E%7CYes%7C%20G%5B%22Full%20bypass%22%5D%0A%20%20%20%20F%20--%3E%7CNo%7C%20E%0A"})]),fallback:e(()=>[...t[1]||(t[1]=[d(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=a('<ul><li><strong>Without Bloom</strong>: Every packet does a HASH lookup (50–80 ns), even if the whitelist is empty</li><li><strong>With Bloom (empty whitelist)</strong>: Bloom reads <code>bloom_map[idx]</code> (ARRAY, ~10 ns), finds 0 → ~10 ns total, saves 40–70 ns</li><li><strong>With Bloom (populated, non-whitelisted IP)</strong>: Bloom returns negative in ~15 ns → ~40–65 ns saved</li><li><strong>False positive cost</strong>: Bloom positive → full HASH lookup (same as without Bloom) + ~15 ns Bloom overhead</li></ul><h2 id="single-core-behavior" tabindex="-1">Single-Core Behavior <a class="header-anchor" href="#single-core-behavior" aria-label="Permalink to &quot;Single-Core Behavior&quot;">​</a></h2><p>At 10 million packets per second on a single core:</p><table tabindex="0"><thead><tr><th>Component</th><th>CPU Time</th><th>% of Core</th></tr></thead><tbody><tr><td>Packet processing (XDP)</td><td>~300 ns/pkt</td><td>30%</td></tr><tr><td>Interrupt handling (NAPI)</td><td>~100 ns/pkt</td><td>10%</td></tr><tr><td>NIC driver overhead</td><td>~80 ns/pkt</td><td>8%</td></tr><tr><td>Kernel stack (for XDP_PASS)</td><td>~60 ns/pkt</td><td>6%</td></tr><tr><td><strong>Total</strong></td><td>~540 ns/pkt</td><td><strong>~54%</strong></td></tr></tbody></table><p>At 10M PPS, a single core handles all packets with ~50–70% utilization. Multi-core RSS (Receive Side Scaling) distributes the load across cores for higher rates.</p><h2 id="scaling-factors" tabindex="-1">Scaling Factors <a class="header-anchor" href="#scaling-factors" aria-label="Permalink to &quot;Scaling Factors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Factor</th><th>Impact</th></tr></thead><tbody><tr><td>RSS queue count</td><td>Linear scaling: 4 queues = ~4× throughput</td></tr><tr><td>XDP mode</td><td><code>native</code> ≈ 2× faster than <code>generic</code>; <code>offload</code> is NIC-dependent</td></tr><tr><td>Whitelist size</td><td>Minimal impact (HASH is O(1) average)</td></tr><tr><td>IP stats map size</td><td>LRU eviction overhead increases slightly with size (log factor)</td></tr><tr><td>Number of active IPs</td><td>Ban map growth affects LRU maintenance; 50K entries ≈ 10% overhead</td></tr><tr><td>Feature toggles</td><td>Each disabled boolean saves ~1 <code>if</code> branch prediction (negligible)</td></tr></tbody></table><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./optimizations">Performance Optimizations</a> — Specific optimization techniques</li><li><a href="./tuning">Performance Tuning</a> — System-level tuning (ethtool, IRQ affinity)</li><li><a href="/pingless-studios-docs/openshield-xdp/architecture/overview">Architecture Overview</a> — Map layout and component roles</li></ul>',9))])}const P=l(p,[["render",m]]);export{k as __pageData,P as default};
